mapper.select:
SELECT SEQ_NO, BATCH_SEQ_NO, TASK_ID, BEAN_NAME, CHECK_DATE, EXECUTE_DATE, TASK_STATUS, DETAIL_COUNT, START_MODE, START_TIME, END_TIME, STOP_FLAG, INSTITUTION_CODE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, (extract(day from A.END_TIME-A.START_TIME) * 86400+ extract(hour from A.END_TIME-A.START_TIME) * 3600 + extract(minute from A.END_TIME-A.START_TIME) * 60+ extract(second from A.END_TIME-A.START_TIME)) * 1000 as processTime, TO_CHAR(A.START_TIME, 'YYYY-MM-DD HH24:MI:SS.ff3') as startTimeStr, TO_CHAR(A.END_TIME, 'YYYY-MM-DD HH24:MI:SS.ff3') as endTimeStr, TO_CHAR(A.EXECUTE_DATE, 'YYYY-MM-DD') as executeDateStr, TO_CHAR(A.CHECK_DATE, 'YYYY-MM-DD') as checkDateStr FROM SYS_PREBATCH_RESULT A
AND TO_CHAR(A.CHECK_DATE, 'YYYY-MM-DD') >= #{startDate}
AND TO_CHAR(A.CHECK_DATE, 'YYYY-MM-DD') <= #{endDate}
AND A.TASK_ID in
#{item}
AND A.TASK_STATUS in
#{item}

mapper.delete:
delete FROM SYS_PREBATCH_RESULT where
INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}
and CHECK_DATE = #{checkDate,jdbcType=DATE}

delete FROM SYS_PREBATCH_RESULT_DETAIL where RESULT_SEQ_NO IN
(
SELECT SEQ_NO FROM SYS_PREBATCH_RESULT
where CHECK_DATE = #{checkDate,jdbcType=DATE}

    AND INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}

)
